#!/usr/bin/env python3
"""
Запуск: python scripts/fix_tenure_levels.py
- Находит дублирующих операторов в БД
- Обновляет start_date из Excel
- Считает стаж в месяцах от start_date до сегодня
- Назначает уровни по стажу
"""
import base64, os, sys, tempfile
from datetime import date, datetime
from decimal import Decimal
from pathlib import Path
import re

PROJECT_ROOT = Path(__file__).parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

XLSX_B64 = ""
TODAY = date(2026, 7, 1)

# Правила уровней (из скриншота):
# Стажёр:  0-15 месяцев
# Новичок: 16-40 месяцев
# Оператор: 41-60 месяцев
# Профи: >= 61 месяцев
LEVEL_RULES = [
    (61, None, "pro"),
    (41, 60,   "operator"),
    (16, 40,   "newbie"),
    (0,  15,   "trainee"),
]

def months_worked(start_date):
    if not start_date:
        return 0
    delta = TODAY - start_date
    return max(0, delta.days // 30)

def level_code_for_months(months):
    for min_m, max_m, code in LEVEL_RULES:
        if months >= min_m and (max_m is None or months <= max_m):
            return code
    return "trainee"

def normalize(name):
    return re.sub(r"\s+", " ", (name or "").strip().lower())

def read_excel(path):
    import openpyxl
    wb = openpyxl.load_workbook(path)
    ws = wb.active
    rows = {}
    for i, row in enumerate(ws.iter_rows(values_only=True)):
        if i == 0: continue
        full_name, _, rate, start_dt, supervisor, email = row
        if not full_name or not str(full_name).strip(): continue
        if isinstance(start_dt, datetime): start_date = start_dt.date()
        elif isinstance(start_dt, date):   start_date = start_dt
        else: start_date = None
        if start_date and start_date > TODAY: start_date = TODAY
        name = str(full_name).strip()
        rows[normalize(name)] = {
            "full_name": name,
            "start_date": start_date,
            "rate": float(rate) if rate else None,
            "email": str(email).strip().lower() if email else "",
        }
    return rows

def main():
    db_url = os.environ.get("DATABASE_URL", "")
    if not db_url:
        print("ERROR: DATABASE_URL не задан"); sys.exit(1)
    if db_url.startswith("postgres://"):
        db_url = db_url.replace("postgres://", "postgresql+psycopg2://", 1)
    elif db_url.startswith("postgresql://") and "+psycopg" not in db_url:
        db_url = db_url.replace("postgresql://", "postgresql+psycopg2://", 1)

    from sqlalchemy import create_engine, select, text
    from sqlalchemy.orm import Session, sessionmaker
    from app.models.entities import Operator, OperatorLevel, OperatorLevelAssignment, now_utc

    engine = create_engine(db_url, pool_pre_ping=True)
    SessionLocal = sessionmaker(bind=engine)
    db = SessionLocal()

    # ── Шаг 1: дубликаты в БД ──────────────────────────────────────
    print("\n=== ПРОВЕРКА ДУБЛЕЙ В БД ===")
    all_ops = list(db.scalars(select(Operator)))
    
    by_name = {}
    by_email = {}
    dups_name, dups_email = [], []
    
    for op in all_ops:
        key = normalize(op.full_name)
        if key in by_name:
            dups_name.append((by_name[key], op))
        else:
            by_name[key] = op
        
        if op.email:
            ekey = op.email.lower().strip()
            if ekey in by_email:
                dups_email.append((by_email[ekey], op))
            else:
                by_email[ekey] = op

    if dups_name:
        print(f"Дубли по ФИО ({len(dups_name)}):")
        for a, b in dups_name:
            print(f"  #{a.id} {a.full_name} | #{b.id} {b.full_name}")
    else:
        print("Дублей по ФИО: нет")
    
    if dups_email:
        print(f"Дубли по email ({len(dups_email)}):")
        for a, b in dups_email:
            print(f"  {a.email}: #{a.id} {a.full_name} | #{b.id} {b.full_name}")
    else:
        print("Дублей по email: нет")

    # ── Шаг 2: загрузить Excel ─────────────────────────────────────
    raw = base64.b64decode(XLSX_B64)
    with tempfile.NamedTemporaryFile(suffix=".xlsx", delete=False) as tmp:
        tmp.write(raw); tmp_path = tmp.name
    excel_rows = read_excel(tmp_path)
    os.unlink(tmp_path)

    # ── Шаг 3: загрузить уровни ────────────────────────────────────
    levels = {lv.code: lv for lv in db.scalars(select(OperatorLevel))}
    print(f"\nУровни в БД: {list(levels.keys())}")

    # ── Шаг 4: обновить start_date + назначить уровень ─────────────
    print("\n=== ОБНОВЛЕНИЕ СТАЖА И УРОВНЕЙ ===")
    print(f"{'ФИО':<40} {'Стаж':>5}  Уровень          Действие")
    print("─" * 75)

    updated = 0
    not_found_in_excel = []

    # Только уникальные (не дубли)
    dup_ids = {b.id for _, b in dups_name} | {b.id for _, b in dups_email}

    for op in all_ops:
        if op.id in dup_ids:
            continue  # дубли пропускаем

        key = normalize(op.full_name)
        excel_row = excel_rows.get(key)
        
        # Ищем по email если не нашли по ФИО
        if not excel_row and op.email:
            for ekey, erow in excel_rows.items():
                if erow["email"] == op.email.lower().strip():
                    excel_row = erow
                    break

        if excel_row:
            start_date = excel_row["start_date"]
        else:
            # Если не в Excel — считаем от created_at
            start_date = op.start_date or op.created_at.date()
            not_found_in_excel.append(op.full_name)

        # Обновляем start_date
        op.start_date = start_date
        
        # Считаем стаж
        tenure_months = months_worked(start_date)
        code = level_code_for_months(tenure_months)
        level = levels.get(code)

        if not level:
            print(f"  WARN: уровень {code} не найден в БД, пропуск")
            continue

        # Назначаем уровень
        assignment = db.scalar(
            select(OperatorLevelAssignment).where(
                OperatorLevelAssignment.operator_id == op.id
            )
        )
        if assignment:
            old_code = levels.get(
                next((k for k, v in levels.items() if v.id == assignment.level_id), "?"),
                type("", (), {"code": "?"})()
            )
            action = f"обновлён ({assignment.level_id}→{level.id})" if assignment.level_id != level.id else "без изменений"
            assignment.level_id = level.id
            assignment.assignment_type = "auto"
            assignment.is_manual = False
        else:
            assignment = OperatorLevelAssignment(
                operator_id=op.id,
                level_id=level.id,
                assignment_type="auto",
                is_manual=False,
                assigned_at=now_utc(),
            )
            db.add(assignment)
            action = "создан"

        print(f"  {op.full_name:<40} {tenure_months:>3}м  {level.name:<16}  {action}")
        updated += 1

    db.commit()

    print("─" * 75)
    print(f"\nОбновлено: {updated} операторов")
    if not_found_in_excel:
        print(f"\nНе найдены в Excel ({len(not_found_in_excel)}) — использована дата создания:")
        for n in not_found_in_excel:
            print(f"  - {n}")
    if dups_name or dups_email:
        print(f"\nДубли пропущены — требуют ручного разрешения:")
        for a, b in dups_name:
            print(f"  ФИО: #{a.id} {a.full_name} и #{b.id} {b.full_name}")

    db.close()
    print("\n✓ Готово")

if __name__ == "__main__":
    main()
